// ReSharper disable StringLiteralTypo
namespace Atc.Rest.Api.Generator.Cli.Tests.Gates;

/// <summary>
/// Runtime gate for how the generated TypeScript clients (Fetch and Axios) surface error responses -
/// the 3.0 error contract, where a server generated by this project answers every error with an
/// RFC 9457 ProblemDetails (<c>application/problem+json</c>) and puts the handler's message in
/// <c>detail</c>. Executes the generated client against a mocked transport.
/// <para>
/// Asserts, for both clients:
/// </para>
/// <list type="bullet">
///   <item><description>the message is the ProblemDetails <c>detail</c>, and <c>detail</c>/<c>title</c>/<c>body</c> are exposed;</description></item>
///   <item><description>a 400 without <c>errors</c> is <c>badRequest</c> with <c>errors: {}</c> (not <c>serverError</c>);</description></item>
///   <item><description>a media type with parameters (<c>; v=1.0</c>) and in mixed case is still JSON;</description></item>
///   <item><description>a JSON-string and a <c>text/plain</c> error body become the message;</description></item>
///   <item><description>an empty error body falls back to <c>HTTP {status}</c> when there is no status text;</description></item>
///   <item><description>an unmapped 4xx is <c>clientError</c>, a 5xx <c>serverError</c>;</description></item>
///   <item><description>a custom error model is available as <c>body</c>.</description></item>
/// </list>
/// Self-skips without a Node toolchain, but fails under CI where Node is provisioned.
/// </summary>
[Trait("Category", "TypeScriptToolchain")]
public sealed class TypeScriptClientErrorContractGateTests
{
    [Fact]
    public void GeneratedFetchClient_ErrorResponses_FollowTheErrorContract()
        => RunGate(TypeScriptHttpClient.Fetch, FetchHarness, FetchPackageJson);

    [Fact]
    public void GeneratedAxiosClient_ErrorResponses_FollowTheErrorContract()
        => RunGate(TypeScriptHttpClient.Axios, AxiosHarness, AxiosPackageJson);

    private static void RunGate(
        TypeScriptHttpClient httpClient,
        string harness,
        string packageJson)
    {
        if (!NodeToolchain.IsAvailable(out var skipReason))
        {
            if (IsContinuousIntegration())
            {
                Assert.Fail(skipReason + " (running under CI where the behaviour gate is required)");
            }

            Assert.Skip(skipReason);
        }

        var doc = OpenApiDocumentHelper.TryParseYaml(SpecYaml, "ErrorContract.yaml", out var document)
            ? document
            : null;
        Assert.NotNull(doc);

        var workDir = Path.Combine(Path.GetTempPath(), "atc-ts-error-contract", Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(workDir);

        try
        {
            var outputPath = Path.Combine(workDir, "generated");
            Directory.CreateDirectory(outputPath);
            TypeScriptClientGenerationService.Generate(
                doc,
                outputPath,
                new TypeScriptClientConfig
                {
                    HttpClient = httpClient,
                    HooksStyle = TypeScriptHooksStyle.None,
                    GenerateFileHeaders = true,
                    Scaffold = false,
                });

            File.WriteAllText(Path.Combine(workDir, "package.json"), packageJson);
            File.WriteAllText(Path.Combine(workDir, "tsconfig.json"), TsConfig);
            File.WriteAllText(Path.Combine(workDir, "harness.mts"), harness + Cases);

            var install = NodeToolchain.RunNpm(
                "install --no-audit --no-fund --loglevel=error",
                workDir,
                TimeSpan.FromMinutes(5));
            Assert.True(
                install.ExitCode == 0,
                $"npm install failed (exit {install.ExitCode}):\n{install.Output}");

            var run = NodeToolchain.RunNpx(
                "tsx harness.mts",
                workDir,
                TimeSpan.FromMinutes(3));

            Assert.True(
                run.ExitCode == 0,
                $"Generated {httpClient} client error-contract gate failed (exit {run.ExitCode}):\n{run.Output}");
        }
        finally
        {
            TryDeleteDirectory(workDir);
        }
    }

    private const string SpecYaml = """
        openapi: 3.0.1
        info:
          title: ErrorContract
          version: 1.0.0
        paths:
          /items/{id}:
            get:
              operationId: getItem
              parameters:
                - name: id
                  in: path
                  required: true
                  schema:
                    type: integer
              responses:
                '200':
                  description: The item.
                  content:
                    application/json:
                      schema:
                        type: string
                '404':
                  description: Not Found
        """;

    private const string FetchPackageJson = """
        {
          "name": "fetch-error-contract-gate",
          "version": "0.0.0",
          "private": true,
          "type": "module",
          "devDependencies": {
            "tsx": "^4.19.0",
            "typescript": "^5.6.0"
          }
        }
        """;

    private const string AxiosPackageJson = """
        {
          "name": "axios-error-contract-gate",
          "version": "0.0.0",
          "private": true,
          "type": "module",
          "dependencies": {
            "axios": "^1.7.0"
          },
          "devDependencies": {
            "tsx": "^4.19.0",
            "typescript": "^5.6.0"
          }
        }
        """;

    private const string TsConfig = """
        {
          "compilerOptions": {
            "target": "ES2020",
            "lib": ["ES2020", "DOM"],
            "module": "ESNext",
            "moduleResolution": "bundler",
            "strict": true,
            "esModuleInterop": true,
            "skipLibCheck": true,
            "noEmit": true
          }
        }
        """;

    // Mocked global fetch: `respond` installs the next Response the client receives.
    private const string FetchHarness = """
        import { ApiClient } from './generated/client/ApiClient';
        import { ItemsClient } from './generated/client/ItemsClient';

        let nextResponse: () => Response = () => new Response(null, { status: 500 });
        let calls = 0;

        (globalThis as any).fetch = async () => {
          calls += 1;
          return nextResponse();
        };

        function respond(body: string, contentType: string | null, status: number, statusText = ''): void {
          nextResponse = () => new Response(body.length === 0 ? null : body, {
            status,
            statusText,
            headers: contentType === null ? {} : { 'Content-Type': contentType },
          });
        }

        const client: any = new ApiClient('http://localhost');
        function transportCalls(): number { return calls; }

        """;

    // Mocked Axios adapter: the raw wire body goes through the instance's transformResponse, exactly
    // as for a real call. The adapter is set before the ApiClient creates its instance.
    private const string AxiosHarness = """
        import axios from 'axios';
        import { ApiClient } from './generated/client/ApiClient';
        import { ItemsClient } from './generated/client/ItemsClient';

        let currentAdapter: (config: any) => Promise<any> = () => Promise.reject(new Error('no adapter configured'));
        let calls = 0;

        axios.defaults.adapter = ((config: any) => {
          calls += 1;
          return currentAdapter(config);
        }) as any;

        function respond(body: string, contentType: string | null, status: number, statusText = ''): void {
          currentAdapter = (config: any) => Promise.resolve({
            data: body,
            status,
            statusText,
            headers: contentType === null ? {} : { 'content-type': contentType },
            config,
            request: {},
          });
        }

        const client: any = new ApiClient('http://localhost');
        function transportCalls(): number { return calls; }

        """;

    // The error cases, shared by both clients.
    private const string Cases = """
        const failures: string[] = [];
        function check(name: string, cond: boolean, detail: string): void {
          if (!cond) {
            failures.push(name + ': ' + detail);
          }
        }

        async function main(): Promise<void> {
          // E1: 404 ProblemDetails with detail -> notFound, message = detail, fields exposed.
          respond(JSON.stringify({ type: 'https://tools.ietf.org/html/rfc9110#section-15.5.5', title: 'Not Found', status: 404, detail: 'Item 42 was not found.' }), 'application/problem+json', 404);
          const before = transportCalls();
          const r1 = await client.request('get', '/items/42');
          check('E1 transport-invoked', transportCalls() > before, 'the mocked transport was never called');
          check('E1 arm', r1.status === 'notFound', 'expected notFound, got ' + r1.status);
          check('E1 message', r1.error?.message === 'Item 42 was not found.', 'expected the detail as message, got ' + JSON.stringify(r1.error?.message));
          check('E1 detail', r1.error?.detail === 'Item 42 was not found.', 'expected detail, got ' + JSON.stringify(r1.error?.detail));
          check('E1 title', r1.error?.title === 'Not Found', 'expected title, got ' + JSON.stringify(r1.error?.title));
          check('E1 body', r1.error?.body?.status === 404, 'expected the parsed body, got ' + JSON.stringify(r1.error?.body));

          // E2: 400 ProblemDetails without errors -> badRequest with errors {}.
          respond(JSON.stringify({ title: 'Bad Request', status: 400, detail: 'The id must be positive.' }), 'application/problem+json', 400);
          const r2 = await client.request('get', '/items/-1');
          check('E2 arm', r2.status === 'badRequest', 'expected badRequest, got ' + r2.status);
          check('E2 errors', r2.error?.errors !== undefined && Object.keys(r2.error.errors).length === 0, 'expected errors {}, got ' + JSON.stringify(r2.error?.errors));
          check('E2 message', r2.error?.message === 'The id must be positive.', 'expected the detail as message, got ' + JSON.stringify(r2.error?.message));

          // E3: 400 validation problem, media type with a parameter -> badRequest with errors.
          respond(JSON.stringify({ title: 'One or more validation errors occurred.', status: 400, errors: { reason: ['The reason is too long.'] } }), 'application/problem+json; v=1.0', 400);
          const r3 = await client.request('get', '/items/1');
          check('E3 arm', r3.status === 'badRequest', 'expected badRequest, got ' + r3.status);
          check('E3 errors', r3.error?.errors?.reason?.[0] === 'The reason is too long.', 'expected errors.reason, got ' + JSON.stringify(r3.error?.errors));

          // E4: 409 JSON-string body -> conflict, message = the string.
          respond(JSON.stringify('The item already exists.'), 'application/json', 409);
          const r4 = await client.request('get', '/items/1');
          check('E4 arm', r4.status === 'conflict', 'expected conflict, got ' + r4.status);
          check('E4 message', r4.error?.message === 'The item already exists.', 'expected the string as message, got ' + JSON.stringify(r4.error?.message));
          check('E4 body', r4.error?.body === 'The item already exists.', 'expected the string as body, got ' + JSON.stringify(r4.error?.body));

          // E5: 422 text/plain body -> unprocessableEntity, message = the text.
          respond('The item cannot be enabled while it is archived.', 'text/plain; charset=utf-8', 422);
          const r5 = await client.request('get', '/items/1');
          check('E5 arm', r5.status === 'unprocessableEntity', 'expected unprocessableEntity, got ' + r5.status);
          check('E5 message', r5.error?.message === 'The item cannot be enabled while it is archived.', 'expected the text as message, got ' + JSON.stringify(r5.error?.message));

          // E6: 404 with an empty body, no Content-Type and no status text -> notFound, message 'HTTP 404'.
          respond('', null, 404, '');
          const r6 = await client.request('get', '/items/1');
          check('E6 arm', r6.status === 'notFound', 'expected notFound, got ' + r6.status);
          check('E6 message', r6.error?.message === 'HTTP 404', 'expected "HTTP 404", got ' + JSON.stringify(r6.error?.message));

          // E7: unmapped 4xx (405) -> clientError.
          respond(JSON.stringify({ title: 'Method Not Allowed', status: 405 }), 'application/problem+json', 405);
          const r7 = await client.request('get', '/items/1');
          check('E7 arm', r7.status === 'clientError', 'expected clientError, got ' + r7.status);
          check('E7 message', r7.error?.message === 'Method Not Allowed', 'expected the title as message, got ' + JSON.stringify(r7.error?.message));

          // E8: 500 ProblemDetails with detail -> serverError, message = detail.
          respond(JSON.stringify({ title: 'An error occurred while processing your request.', status: 500, detail: 'Database unavailable.' }), 'application/problem+json', 500);
          const r8 = await client.request('get', '/items/1');
          check('E8 arm', r8.status === 'serverError', 'expected serverError, got ' + r8.status);
          check('E8 message', r8.error?.message === 'Database unavailable.', 'expected the detail as message, got ' + JSON.stringify(r8.error?.message));

          // E9: mixed-case media type is still JSON.
          respond(JSON.stringify({ title: 'Conflict', status: 409, detail: 'Changed by someone else.' }), 'Application/Problem+JSON', 409);
          const r9 = await client.request('get', '/items/1');
          check('E9 message', r9.error?.message === 'Changed by someone else.', 'expected the detail as message, got ' + JSON.stringify(r9.error?.message));

          // E10: a custom error model -> available as body.
          respond(JSON.stringify({ code: 'E422', message: 'Not allowed.' }), 'application/json', 422);
          const r10 = await client.request('get', '/items/1');
          check('E10 body', r10.error?.body?.code === 'E422', 'expected body.code, got ' + JSON.stringify(r10.error?.body));
          check('E10 message', r10.error?.message === 'Not allowed.', 'expected body.message as message, got ' + JSON.stringify(r10.error?.message));

          // E11: through the generated client, a status the operation's union does not declare is folded into one it
          // does (getItem declares 200 and 404, plus the auto 400): 409/401/418 -> clientError, 503 -> serverError,
          // 201 -> ok; a declared 404 stays notFound. An exhaustive switch over GetItemResult sees every result.
          const items = new ItemsClient(client);
          const folds: [number, string, string][] = [[409, 'application/problem+json', 'clientError'], [401, 'application/problem+json', 'clientError'], [418, 'text/plain', 'clientError'], [503, 'application/problem+json', 'serverError'], [404, 'application/problem+json', 'notFound'], [201, 'application/json', 'ok']];
          for (const [status, contentType, expected] of folds) {
            respond(status === 201 ? JSON.stringify('created') : JSON.stringify({ title: 't', status, detail: 'd' }), contentType, status);
            const r = await items.getItem(1);
            check('E11 ' + status, r.status === expected, 'expected ' + expected + ', got ' + r.status);
            check('E11 ' + status + ' keeps the HTTP status', r.error === undefined || r.error.status === status, 'error.status ' + r.error?.status);
          }

          // E12: through the generated operation (a JSON operation, so the body of a success is read as JSON whatever
          // the Content-Type says), a foreign error body - a proxy's HTML page, a gateway's XML, plain text - is kept as
          // the text its Content-Type says it is: the model did not arrive, but the body is not lost.
          const foreign: [number, string, string][] = [[502, 'text/html; charset=utf-8', '<html><body>Bad gateway</body></html>'], [503, 'application/xml', '<error><reason>down</reason></error>'], [503, 'text/plain; charset=utf-8', 'Service down for maintenance']];
          for (const [status, contentType, body] of foreign) {
            respond(body, contentType, status);
            const r = await items.getItem(1);
            check('E12 ' + contentType + ' arm', r.status === 'serverError', 'expected serverError, got ' + r.status);
            check('E12 ' + contentType + ' body', r.error?.body === body, 'expected the body text, got ' + JSON.stringify(r.error?.body));
          }
          respond('Service down for maintenance', 'text/plain; charset=utf-8', 503);
          const r12 = await items.getItem(1);
          check('E12 text message', r12.error?.message === 'Service down for maintenance', 'expected the text as message, got ' + JSON.stringify(r12.error?.message));

          if (failures.length > 0) {
            console.error('ERROR-CONTRACT FAILURES:\n' + failures.join('\n'));
            process.exit(1);
          }

          console.log('ALL ERROR-CONTRACT CHECKS PASSED');
        }

        main().catch((e) => {
          console.error('HARNESS ERROR', e);
          process.exit(2);
        });
        """;

    private static bool IsContinuousIntegration()
        => string.Equals(Environment.GetEnvironmentVariable("GITHUB_ACTIONS"), "true", StringComparison.OrdinalIgnoreCase)
        || string.Equals(Environment.GetEnvironmentVariable("CI"), "true", StringComparison.OrdinalIgnoreCase);

    private static void TryDeleteDirectory(string path)
    {
        try
        {
            if (Directory.Exists(path))
            {
                Directory.Delete(path, recursive: true);
            }
        }
        catch (IOException)
        {
            // Best-effort cleanup.
        }
        catch (UnauthorizedAccessException)
        {
            // Best-effort cleanup.
        }
    }
}